// Package argo watches Argo CD Applications of Ladder apps and reports their
// sync and health status.
package argo

import (
	"context"
	"log/slog"
	"sort"
	"strings"
	"sync"
	"time"

	"github.com/ladder/ladder-agent/internal/kube"
	"github.com/ladder/ladder-agent/internal/protocol"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/apimachinery/pkg/apis/meta/v1/unstructured"
	"k8s.io/client-go/dynamic/dynamicinformer"
	"k8s.io/client-go/tools/cache"
)

// ManagedLabel marks Applications generated by the "apps" ApplicationSet.
const ManagedLabel = "ladder.dev/managed=true"

const crdPollInterval = 15 * time.Second

type Watcher struct {
	k         *kube.Clients
	namespace string
	log       *slog.Logger

	// OnChange is called for every Application whose status changed.
	OnChange func(protocol.AppsChanged)
	// OnSnapshot is called once the cache is synced.
	OnSnapshot func(protocol.AppsSnapshot)

	mu       sync.RWMutex
	apps     map[string]protocol.AppStatus
	watching bool
}

func NewWatcher(k *kube.Clients, namespace string, log *slog.Logger) *Watcher {
	return &Watcher{k: k, namespace: namespace, log: log, apps: map[string]protocol.AppStatus{}}
}

// Run waits until the Application CRD exists (it does not before setup),
// then watches Applications until ctx is done.
func (w *Watcher) Run(ctx context.Context) {
	if !w.waitForCRD(ctx) {
		return
	}
	factory := dynamicinformer.NewFilteredDynamicSharedInformerFactory(w.k.Dynamic, 0, w.namespace,
		func(o *metav1.ListOptions) { o.LabelSelector = ManagedLabel })
	inf := factory.ForResource(kube.ApplicationGVR).Informer()
	_, _ = inf.AddEventHandler(cache.ResourceEventHandlerFuncs{
		AddFunc:    w.upsert,
		UpdateFunc: func(_, obj any) { w.upsert(obj) },
		DeleteFunc: w.remove,
	})
	factory.Start(ctx.Done())
	defer factory.Shutdown()
	if !cache.WaitForCacheSync(ctx.Done(), inf.HasSynced) {
		return
	}
	w.mu.Lock()
	w.watching = true
	w.mu.Unlock()
	w.log.Info("watching applications", "namespace", w.namespace)
	if w.OnSnapshot != nil {
		w.OnSnapshot(w.Snapshot())
	}
	<-ctx.Done()
}

func (w *Watcher) waitForCRD(ctx context.Context) bool {
	t := time.NewTicker(crdPollInterval)
	defer t.Stop()
	logged := false
	for {
		ok, err := w.k.HasResource(kube.ApplicationGVR)
		if err != nil {
			w.log.Warn("discover application CRD", "err", err)
		}
		if ok {
			return true
		}
		if !logged {
			w.log.Info("application CRD not found, waiting for Argo CD")
			logged = true
		}
		select {
		case <-ctx.Done():
			return false
		case <-t.C:
		}
	}
}

func (w *Watcher) Snapshot() protocol.AppsSnapshot {
	w.mu.RLock()
	defer w.mu.RUnlock()
	apps := make([]protocol.AppStatus, 0, len(w.apps))
	for _, a := range w.apps {
		apps = append(apps, a)
	}
	sort.Slice(apps, func(i, j int) bool { return apps[i].Name < apps[j].Name })
	return protocol.AppsSnapshot{Watching: w.watching, Apps: apps}
}

func (w *Watcher) upsert(obj any) {
	u, ok := obj.(*unstructured.Unstructured)
	if !ok {
		return
	}
	s := project(u)
	w.mu.Lock()
	prev, existed := w.apps[s.Name]
	w.apps[s.Name] = s
	notify := w.watching && (!existed || prev != s)
	w.mu.Unlock()
	if notify && w.OnChange != nil {
		w.OnChange(protocol.AppsChanged{App: s})
	}
}

func (w *Watcher) remove(obj any) {
	if d, ok := obj.(cache.DeletedFinalStateUnknown); ok {
		obj = d.Obj
	}
	u, ok := obj.(*unstructured.Unstructured)
	if !ok {
		return
	}
	w.mu.Lock()
	prev, existed := w.apps[u.GetName()]
	delete(w.apps, u.GetName())
	notify := w.watching && existed
	w.mu.Unlock()
	if notify && w.OnChange != nil {
		w.OnChange(protocol.AppsChanged{App: prev, Deleted: true})
	}
}

// project keeps only the fields Ladder shows, so that Argo CD's frequent
// status writes (reconciledAt and so on) do not produce events.
func project(u *unstructured.Unstructured) protocol.AppStatus {
	str := func(path ...string) string {
		v, _, _ := unstructured.NestedString(u.Object, path...)
		return v
	}
	s := protocol.AppStatus{
		Name:           u.GetName(),
		Namespace:      str("spec", "destination", "namespace"),
		Sync:           str("status", "sync", "status"),
		Health:         str("status", "health", "status"),
		Revision:       str("status", "sync", "revision"),
		OperationPhase: str("status", "operationState", "phase"),
	}
	if s.Revision == "" {
		// Multi-source Applications (chart + values ref) report one revision per source.
		if revs, _, _ := unstructured.NestedStringSlice(u.Object, "status", "sync", "revisions"); len(revs) > 0 {
			s.Revision = revs[0]
		}
	}
	if s.Sync == "" {
		s.Sync = "Unknown"
	}
	if s.Health == "" {
		s.Health = "Unknown"
	}
	s.Message = errorMessage(u)
	return s
}

// errorMessage is what Argo CD reports as wrong with the app: its error
// conditions (ComparisonError, SyncError and so on) and a sync operation that
// failed or is being retried. Empty when nothing is wrong.
func errorMessage(u *unstructured.Unstructured) string {
	var msgs []string
	// A SyncError repeats the operation's message with a prefix: keep the longer one.
	add := func(m string) {
		m = strings.TrimSpace(m)
		if m == "" {
			return
		}
		for i, prev := range msgs {
			if strings.Contains(prev, m) {
				return
			}
			if strings.Contains(m, prev) {
				msgs[i] = m
				return
			}
		}
		msgs = append(msgs, m)
	}
	conds, _, _ := unstructured.NestedSlice(u.Object, "status", "conditions")
	for _, c := range conds {
		m, _ := c.(map[string]any)
		// Argo CD's own rule: a condition is an error if its type ends in "Error".
		if t, _ := m["type"].(string); strings.HasSuffix(t, "Error") {
			msg, _ := m["message"].(string)
			add(msg)
		}
	}
	phase, _, _ := unstructured.NestedString(u.Object, "status", "operationState", "phase")
	retries, _, _ := unstructured.NestedInt64(u.Object, "status", "operationState", "retryCount")
	if phase == "Failed" || phase == "Error" || (phase == "Running" && retries > 0) {
		msg, _, _ := unstructured.NestedString(u.Object, "status", "operationState", "message")
		add(msg)
	}
	return strings.Join(msgs, "\n")
}
